/* dmr - drax manager & resolver
 *
 * the Drax language as data (keywords, functions, modules, operators).
 * dlang_data.c is generated by tools/gen_lang.sh from the interpreter.
 */
#ifndef __DMR_LANG
#define __DMR_LANG

typedef struct dlang_module {
  const char* name;
  const char* const* fns;     /* "name/arity", 0 terminated */
} dlang_module;

typedef struct dlang_op_level {
  const char* level;
  const char* ops;            /* space separated */
} dlang_op_level;

extern const char* const DLANG_KEYWORDS[];      /* 0 terminated */
extern const char* const DLANG_BUILTINS[];      /* "name/arity" */
extern const dlang_module DLANG_MODULES[];      /* name == 0 terminates */
extern const dlang_op_level DLANG_OPERATORS[];  /* level == 0 terminates */

int dlang_is_keyword(const char* s);
int dlang_has_builtin(const char* name, int arity);
int dlang_has_module_fn(const char* mod, const char* name, int arity);

#endif
